    for record in marriages:
        if not isinstance(record,dict):
            raise TypeError('Each marriage interval must be an object')
        individual=record.get('individual'); spouse=record.get('spouse')
        start=record.get('start_date'); end=record.get('end_date'); opened=record.get('open_ended')
        if not isinstance(individual,str) or not isinstance(spouse,str) or not isinstance(start,str) or type(opened) is not bool:
            raise ValueError('Malformed marriage interval')
        calendar_year(start)
        if end is not None:
            if not isinstance(end,str) or opened:
                raise ValueError('A closed marriage interval requires open_ended false')
            calendar_year(end)
            if end<start:
                raise ValueError('Marriage interval ends before it begins')
